with unpacked as (select id, service, host, log_ts, latency_ms, get_json_object(payload_json, '$.user.tier') as user_tier, get_json_object(payload_json, '$.duration') as duration_text from app_logs where service = 'auth') select date_trunc('hour', log_ts) as hour_window, service, percentile_approx(latency_ms, 0.5) as latency_ms_p50, approx_percentile(latency_ms, array(0.25, 0.5, 0.75)) as latency_ms_quartiles from unpacked group by 1, 2 order by latency_ms_p50 desc;
